head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > dataType]<br/>SearchBox 컴포넌트의 데이터 타입을 설정합니다.",
    "validation" : [
        "dataType 속성으로 SearchBox 컴포넌트의 데이터 타입을 설정할 수 있어야 합니다.",
        "dataType 속성은 displayFormat 등 여러 속성에서 참조하며, 바인딩된 데이터 형식과 일치하지 않아도 무관합니다.",
        "'text' (default) 설정 시 텍스트 타입으로 동작합니다.",
        "'number' 설정 시 숫자 타입으로 동작합니다.",
        "'date' 설정 시 날짜 타입으로 동작합니다.",
        "'time' 설정 시 시간 타입으로 동작합니다.",
        "dataType 속성값에 따라 displayFormat 에 설정한 마스크 문자 처리 방식이 달라집니다.",
        "dataType='text' 일때 displayFormat 의 '#' 마스크는 오른쪽 문자부터 매칭되며 '#' 이외의 문자는 그대로 적용됩니다.",
        "dataType='number' 일때 displayFormat 의 '#', '0', ',', '.' 마스크 문자가 사용되어 숫자 포맷으로 표시됩니다.",
        "dataType='date' 일때 displayFormat 의 'y', 'M', 'd', 'E' 마스크 문자가 사용되어 날짜 포맷으로 표시됩니다.",
        "dataType='time' 일때 displayFormat 의 'H', 'm', 's' 마스크 문자가 사용되어 시간 포맷으로 표시됩니다.",
        "getDataType() 메소드로 설정된 dataType 속성값을 조회할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text_display = function(target) {
    let inputElem = target.render.querySelector("input");
    let rtn = inputElem ? inputElem.value : '';
    wf_body_bottom.getObj("scwin").setReturnValue("text(display) : " + rtn);
}

scwin.get_dataType = function(target) {
    wf_body_bottom.getObj("scwin").setReturnValue("getDataType : " + target.getDataType());
}



// target1 : dataType 미설정 (기본값 text)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("langkoKR");
    target1.focus();
    target1.blur();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text_display(target1);
}

scwin.btn_getDataType1_onclick = function (e) {
    scwin.get_dataType(target1);
}

// target2 : dataType=text
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("langkoKR");
    target2.focus();
    target2.blur();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text_display(target2);
}

scwin.btn_getDataType2_onclick = function (e) {
    scwin.get_dataType(target2);
}

// target3 : dataType=number
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("1234567");
    target3.focus();
    target3.blur();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text_display(target3);
}

scwin.btn_getDataType3_onclick = function (e) {
    scwin.get_dataType(target3);
}

// target4 : dataType=date
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("20080501");
    target4.focus();
    target4.blur();
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text_display(target4);
}

scwin.btn_getDataType4_onclick = function (e) {
    scwin.get_dataType(target4);
}

// target5 : dataType=time
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("121521");
    target5.focus();
    target5.blur();
};

scwin.btn_getText5_onclick = function (e) {
    scwin.get_text_display(target5);
}

scwin.btn_getDataType5_onclick = function (e) {
    scwin.get_dataType(target5);
}

// target6 : dataType=number, 바인딩 데이터(text 형식)와 불일치해도 number 로 동작
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("9876543");
    target6.focus();
    target6.blur();
};

scwin.btn_getText6_onclick = function (e) {
    scwin.get_text_display(target6);
}

scwin.btn_getDataType6_onclick = function (e) {
    scwin.get_dataType(target6);
}



scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i <= 6; i ++)
        eval("scwin.btn_setValue"+i+"_onclick()");
}

scwin.btn_getAllText_onclick = function (e) {
    for (var i = 1; i <= 6; i ++)
        eval("scwin.btn_getText"+i+"_onclick()");
};

scwin.btn_getAllDataType_onclick = function (e) {
    for (var i = 1; i <= 6; i ++)
        eval("scwin.btn_getDataType"+i+"_onclick()");
};
